"""Local, in-process document retrieval backend."""

import asyncio
from typing import Any, Dict, List, Optional

import structlog

from rasa.builder.document_retrieval.base import (
    BaseRetriever,
    RetrievalResponse,
    RetrievalResult,
)
from rasa.builder.document_retrieval.local.config import (
    LocalRetrievalConfig,
    SearchMode,
)
from rasa.builder.document_retrieval.local.embedding import Embedder, build_embedder
from rasa.builder.document_retrieval.local.index import (
    LocalIndex,
    ingest_vector_artifact,
)
from rasa.builder.document_retrieval.local.vector_store import StoreHit
from rasa.builder.document_retrieval.source import SourceDocument

structlogger = structlog.get_logger()

# Columns a caller may filter on
_FILTERABLE_FIELDS = frozenset({"topic"})


def _build_where(
    filters: Optional[Dict[str, Any]], default_topic: Optional[str]
) -> Optional[str]:
    """Turn a structured filter dict into a LanceDB ``where`` predicate."""
    effective: Dict[str, Any] = {
        k: v for k, v in (filters or {}).items() if k in _FILTERABLE_FIELDS
    }
    if "topic" not in effective and default_topic:
        effective["topic"] = default_topic
    if not effective:
        return None
    return " AND ".join(
        f"{field} = '{str(value).replace(chr(39), chr(39) * 2)}'"
        for field, value in effective.items()
    )


class LocalDocumentRetrieval(BaseRetriever):
    """Retrieves documentation chunks from a local vector store.

    Build one with :meth:`from_artifact` (serve a prebuilt parquet artifact) or
    :meth:`from_documents` (embed a corpus). The constructor only wraps an index
    that is already filled.
    """

    def __init__(self, index: LocalIndex, embedder: Embedder) -> None:
        """Serve ``index``, embedding queries with ``embedder``. Does no I/O.

        Args:
            index: A filled index; its config also sets how searches run.
            embedder: Query embedder; must match the index's embedding config.
        """
        self._config = index.config
        self._store = index.store
        self._embedder = embedder

    @classmethod
    def from_artifact(
        cls,
        config: LocalRetrievalConfig,
        parquet_path: str,
        *,
        corpus: str,
        embedder: Optional[Embedder] = None,
    ) -> "LocalDocumentRetrieval":
        """Serve the precomputed vectors in a parquet artifact (no embedding).

        Args:
            config: How to search, and where the index is cached.
            parquet_path: Path to the prebuilt parquet vector artifact.
            corpus: Name of the corpus the artifact holds; each corpus is cached
                in its own folder.
            embedder: Query embedder to reuse; built from ``config.embedder``
                when omitted.

        Raises:
            IndexConfigMismatch: If the artifact was built with another
                embedding config.
        """
        embedder = embedder or build_embedder(config.embedder)
        index = LocalIndex(config, corpus=corpus)
        ingest_vector_artifact(index, parquet_path, embedder.dim)
        return cls(index, embedder)

    @classmethod
    def from_documents(
        cls,
        config: LocalRetrievalConfig,
        documents: List[SourceDocument],
        corpus_version: str,
        *,
        corpus: str,
        embedder: Optional[Embedder] = None,
    ) -> "LocalDocumentRetrieval":
        """Embed ``documents`` into the index and serve it (evaluator / local dev).

        Args:
            config: How to search, and where the index is cached.
            documents: The full corpus, as whole documents.
            corpus_version: Snapshot id of ``documents``; an index already
                stamped with it is reused without embedding.
            corpus: Name of the corpus ``documents`` belong to; each corpus is
                cached in its own folder.
            embedder: Embedder to reuse; built from ``config.embedder`` when
                omitted.

        Raises:
            ValueError: If ``documents`` is empty or produces no chunks.
        """
        # Lazy import so the copilot serving path never pulls in the offline
        # build pipeline.
        from rasa.builder.document_retrieval.local.build_pipeline import sync_index

        embedder = embedder or build_embedder(config.embedder)
        index = LocalIndex(config, corpus=corpus)
        sync_index(index, documents, corpus_version, embedder)
        return cls(index, embedder)

    async def retrieve(
        self,
        query: str,
        *,
        top_k: Optional[int] = None,
        filters: Optional[Dict[str, Any]] = None,
    ) -> RetrievalResponse:
        """Retrieve the top-k chunks for a query.

        The embedding and vector search block, so they run in a worker thread
        and leave the event loop free. Never raises, apart from cancellation.
        """
        try:
            hits = await asyncio.to_thread(self._search, query, top_k, filters)
        except Exception as e:
            structlogger.error(
                "local_document_retrieval.retrieve.failed",
                error=str(e),
            )
            return RetrievalResponse.failed(str(e))

        return RetrievalResponse.of([self._hit_to_result(hit) for hit in hits])

    def _search(
        self,
        query: str,
        top_k: Optional[int],
        filters: Optional[Dict[str, Any]],
    ) -> List[StoreHit]:
        """Embed ``query`` and search the store. Blocking; runs off the loop.

        Safe to run concurrently: the embedder only reads its model and
        tokenizer per call, and the store's searches are read-only.
        """
        query_vector = self._embedder.encode_one(query)
        where = _build_where(filters, self._config.topic_filter)
        limit = top_k if top_k is not None else self._config.top_k
        return self._store.search(
            query_vector=query_vector,
            query_text=query,
            top_k=limit,
            hybrid=self._config.search_mode is SearchMode.HYBRID,
            where=where,
        )

    @staticmethod
    def _hit_to_result(hit: StoreHit) -> RetrievalResult:
        """Convert a store hit into a RetrievalResult."""
        chunk = hit.chunk
        return RetrievalResult(
            content=chunk.text,
            title=chunk.title,
            url=chunk.url,
            score=hit.score,
            source_id=chunk.doc_id,
            metadata={"topic": chunk.topic, "chunk_index": chunk.chunk_index},
        )
